const config = $input.first().json;
const owner = typeof config.owner === 'string' ? config.owner.trim() : '';
const repo = typeof config.repo === 'string' ? config.repo.trim() : '';
if (!/^[A-Za-z0-9-]+$/.test(owner) || !/^[A-Za-z0-9_.-]+$/.test(repo) || repo === '.' || repo === '..') {
  throw new Error('Укажите отдельные имена owner и repo');
}
return [{json: {owner, repo}}];

const response = $input.first().json;
const status = response.statusCode;
if (status === 404) {
  throw new Error('Репозиторий не найден или недоступен с текущими GitHub credentials');
}
if (status === 401 || status === 403 || status === 429) {
  throw new Error('GitHub отклонил проверку репозитория (HTTP ' + status + '). Проверьте credentials, права и лимит запросов');
}
const repository = response.body?.full_name;
if (status !== 200 || typeof repository !== 'string' || !/^[A-Za-z0-9-]+\/[A-Za-z0-9_.-]+$/.test(repository)) {
  throw new Error('GitHub не подтвердил репозиторий (HTTP ' + status + ')');
}
const end = $now.setZone('Europe/Moscow').startOf('second');
const start = end.minus({ hours: 168 });
const from = start.toUTC().toISO({ suppressMilliseconds: true });
const through = end.minus({ seconds: 1 }).toUTC().toISO({ suppressMilliseconds: true });
const range = from + '..' + through;
const base = 'repo:' + repository + ' is:issue ';
return [{json: {
  repository,
  from: start.toISO(), to: end.toISO(),
  queries: {
    created: base + 'created:' + range,
    closed: base + 'closed:' + range,
    updated: base + 'updated:' + range,
    triage: base + 'created:' + range + ' label:needs-triage',
  }
}}];

const pages = $input.all().map(item => item.json);
if (pages.length === 0) throw new Error('GitHub did not return a response');
if (pages.some(page => page.incomplete_results)) {
  throw new Error('GitHub returned incomplete search results');
}
const count = pages[0].total_count;
const issues = pages.flatMap(page => page.items ?? []);
if (!Number.isInteger(count) || count > 1000 || issues.length !== count) {
  throw new Error('GitHub search was truncated: ' + issues.length + '/' + count);
}
return [{json: {count, issues}}];

