const period = $('Период последних 7 суток').first().json;
const created = $('Собрать созданные').first().json;
const closed = $('Собрать закрытые').first().json;
const updated = $('Собрать обновлённые').first().json;
const triage = $('Собрать needs-triage').first().json;
const from = new Date(period.from);
const to = new Date(period.to);
const labels = ['needs-triage', 'bug', 'task', 'feature-request'];
const groups = new Map();
const inPeriod = (issues, field) => issues.filter(issue => {
  const timestamp = Date.parse(issue[field]);
  return !issue.pull_request && timestamp >= from.getTime() && timestamp < to.getTime();
});
const newIssues = inPeriod(created.issues, 'created_at');
for (const issue of newIssues) {
  const names = new Set((issue.labels ?? []).map(label =>
    typeof label === 'string' ? label : label.name
  ));
  const type = labels.find(name => names.has(name)) ?? 'без типа';
  const author = issue.user?.login ?? 'неизвестен';
  const key = JSON.stringify([type, author]);
  groups.set(key, (groups.get(key) ?? 0) + 1);
}
const rows = [...groups]
  .map(([key, count]) => [...JSON.parse(key), count])
  .sort((a, b) => a[0].localeCompare(b[0]) || a[1].localeCompare(b[1]));
const date = value => new Intl.DateTimeFormat('ru-RU', {
  timeZone: 'Europe/Moscow', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23'
}).format(new Date(value));
const periodText = date(from) + ' — ' + date(to) + ' (МСК)';
return [{json: {
  repository: period.repository,
  period: {from: period.from, to: period.to, text: periodText},
  counts: {
    created: newIssues.length,
    closed: inPeriod(closed.issues, 'closed_at').length,
    updated: inPeriod(updated.issues, 'updated_at').length,
    needsTriage: inPeriod(triage.issues, 'created_at').length,
  },
  rows: rows.map(([type, author, count]) => ({type, author, count})),
}}];
